import js from '@eslint/js';
import tseslint from 'typescript-eslint';

/**
 * One flat config for the whole monorepo (`pnpm lint` runs `eslint .` here).
 *
 * Deliberately close to the recommended sets: TypeScript strict mode already
 * catches most of what a long rule list would, so lint is for the mistakes
 * the compiler allows. Prettier owns formatting; no stylistic rules here.
 */
export default tseslint.config(
  {
    ignores: [
      '**/node_modules/**',
      '**/dist/**',
      '**/build/**',
      // Generated by Expo: native projects (prebuild) and route types.
      'apps/mobile/ios/**',
      'apps/mobile/android/**',
      'apps/mobile/.expo/**',
      'apps/mobile/expo-env.d.ts',
    ],
  },

  js.configs.recommended,
  ...tseslint.configs.recommended,

  {
    linterOptions: { reportUnusedDisableDirectives: 'error' },
    rules: {
      // `_name` marks a value as deliberately unused, e.g. a field
      // destructured out so the rest can be passed on without it.
      '@typescript-eslint/no-unused-vars': [
        'error',
        {
          argsIgnorePattern: '^_',
          varsIgnorePattern: '^_',
          destructuredArrayIgnorePattern: '^_',
          caughtErrors: 'none',
        },
      ],
      // Type-only imports are compiled away; keep them visibly separate.
      '@typescript-eslint/consistent-type-imports': ['error', { fixStyle: 'inline-type-imports' }],
      // The server logs through pino (redacts coordinates) and the app has
      // no console in production paths. A stray console.log is a leak.
      'no-console': 'error',
    },
  },
);
